+  WorkspaceLayout layout;
+  layout.add_bytes(max_aligned);
+  EXPECT_THROW(layout.add_bytes(kWorkspaceAlignment), std::runtime_error);
+  EXPECT_THROW(layout.add_bytes(1, kStrongerAlignment), std::runtime_error);
