+  ASSERT_EQ(cudaEventCreateWithFlags(&producer_done, cudaEventDisableTiming), cudaSuccess);
+  ASSERT_EQ(cudaEventCreateWithFlags(&consumer_done, cudaEventDisableTiming), cudaSuccess);
