+  consume_table<<<1, kTableElements, 0, streams_[1]>>>(workspace.get<int>(table, streams_[1]),
+                                                       workspace.get<int>(scratch, streams_[1]));
+  ASSERT_EQ(cudaEventRecord(consumer_done, streams_[1]), cudaSuccess);
